    # 1) closest to resources
    # 2) maximize distance from opponent (avoid entanglement)
    # 3) maximize mobility (avoid traps)
    # 4) minimize step cost
    best = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
